// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Felsefe tarihi: İlk Çağ ve Orta Çağ (zor).
const ozSocialscience11Zor = <(String, String, List<String>, String)>[
  ('Anaksimandros\'a göre Dünya, evrenin merkezinde hiçbir şeye dayanmadan nasıl durur?', 'Her yönden eşit uzaklıkta olduğu için hiçbir yöne düşmesine neden yoktur', ['Büyük bir okyanusun üzerinde bir salın gibi yüzdüğü için hiçbir yöne düşmez', 'Bir devin omuzlarında taşındığı için aşağıya inmesi ancak onun iradesiyle olur', 'Merkezî ateşin çekimiyle yerinde tutulduğu için başka bir desteğe gerek duymaz'], 'Anaksimandros dengeyi simetriyle açıklar: merkezde ve her yerden eşit uzaklıkta olan Dünya için herhangi bir yönde hareket etmek için yeterli neden yoktur. Bu, yeterli neden fikrinin erken bir örneği sayılır.'),
  ('Anaksagoras\'a göre madde nasıl bir yapıdadır?', 'Sonsuz bölünebilen tohumlardan oluşur; her şeyin içinde her şeyden bir pay bulunur', ['Bölünemeyen, aynı türden küçük atomlardan oluşur ve atomlar boşlukta hareket eder', 'Yalnızca sudan oluşur ve su yoğunlaşıp seyrelerek öbür şeylere dönüşür', 'Sayılarla ifade edilen noktalardan oluşur ve her sayı bir ilkeye karşılık gelir'], 'Anaksagoras\'ın "tohumlar" anlayışında hiçbir şey tümüyle saf değildir; her şeyde her şeyin bir parçası vardır. Bu yüzden bir şeyin görünüşü baskın payına göre belirlenir.'),
  ('Atomcular, Parmenides\'in "boşluk yoktur" tezine karşı neden boşluğun var olduğunu kabul etmiştir?', 'Hareketin ve atomların yer değiştirmesinin mümkün olması için bir boşluk gerekir', ['Boşluğun duyularla doğrudan görülebilir olduğunu göstermek istemeleri nedeniyle', 'Boşluğun tanrısal bir ilke olduğuna ve her yerde yaşadığına inanmaları nedeniyle', 'Boşluk olmadan atomların bölünemeyeceğini düşündükleri için'], 'Atomcular çokluğu ve hareketi kurtarmak istedi. Atomların hareket edebilmesi için içinde yer değiştirecekleri bir boşluk, yani var olmayan bir şey kabul edilmeliydi.'),
  ('Protagoras\'ın tanrılar konusundaki tutumunu en iyi hangi ifade yansıtır?', 'Tanrıların var olup olmadığını bilemem; konu karanlık ve insan ömrü kısadır', ['Tanrılar yalnız soylulara görünür ve halk bu nedenle tapınaklardaki törenlere katılmamalıdır', 'Tanrılar yalnızca doğa yasalarının başka bir adıdır, ayrıca bir kişiliği yoktur', 'Tanrılar insanın kendi icadıdır ve kesinlikle yoktur, buna ilişkin hiçbir tartışma gerekmez'], 'Protagoras\'a atfedilen sözde tanrıların var olup olmadığını bilemeyeceğini söyler. Bu bilinemezci tutum onun göreceliğiyle uyumludur.'),
  ('Megaralı Eubulides\'e atfedilen "yalancı paradoksu"nun özünde hangi sorun yatar?', 'Kendi doğruluğunu ya da yanlışlığını ileri süren bir önermenin çelişkiye yol açması', ['Sonsuz sayıda atomun varlığı ve atomların boşlukta yer değiştirmesinin imkânsızlığı', 'Hareketin sonsuz bölünebilirliği yüzünden hiçbir mesafenin aşılamaması', 'Tanrının varlığının ne kanıtlanabilmesi ne de tümden çürütülebilmesi'], '"Şimdi söylediğim yalandır" türü bir cümle doğru kabul edilirse yanlış, yanlış kabul edilirse doğru çıkar. Megara okulu bu tür paradokslarla mantığın gelişmesine katkı yaptı.'),
  ('Krates\'in eşi Hipparkhia\'yı felsefe tarihinde dikkat çekici kılan nedir?', 'Kadın olarak Kinik felsefeyi benimseyip erkeklerle birlikte felsefe yapması', ['Platon\'un Akademia\'sına ilk kadın öğrenci olarak kabul edilmiş olması', 'Stoa okulunu kurup öğretisini Kıbrıs\'ta yaymış olması', 'Atina\'da bir devlet görevi üstlenip kentin ilk kadın yöneticisi olması'], 'Hipparkhia varlıklı bir aileden gelmesine karşın Krates\'le evlenip Kinik yaşamı benimsedi. Antik Yunan\'da bilinen az sayıdaki kadın filozoftan biridir.'),
  ('Platon\'a göre demokrasinin tiranlığa dönüşmesine yol açan temel etken nedir?', 'Aşırı özgürlük sevgisinin düzeni çözüp halkın bir halk önderine sığınması', ['Savaşta uğranan büyük bir yenilgi', 'Zenginlerin yönetime tümüyle çekilmesi', 'Filozofların yönetimi ele geçirmesi'], 'Platon demokraside özgürlüğün doyumsuz hâle gelmesinin otoriteyi yıktığını, düzensizlikten bıkan halkın güçlü bir lidere yöneldiğini anlatır.'),
  ('Aristoteles\'in "Gelecekteki deniz savaşı" örneğinde yarınki bir olay hakkında sorun nedir?', 'Henüz belirlenmemiş bir geleceğe ilişkin önermelerin şimdiden doğru ya da yanlış sayılıp sayılamayacağı', ['Savaş stratejilerinin nasıl planlanacağı', 'Donanmanın kaç gemiden oluştuğu', 'Denizcilerin hangi tanrıya yalvardığı'], 'Aristoteles, "Yarın deniz savaşı olacak" önermesinin bugün doğru ya da yanlış olup olmadığı sorusunu geleceğin belirsizliği (gelecek tikeller) bağlamında tartışır.'),
  ('Aristoteles\'in "boşluk"un var olamayacağını savunma gerekçesi nedir?', 'Boşlukta cisimlerin hızının sonsuz olması gerekeceği, bunun saçma olduğu', ['Boşluğun yalnız tanrıların alanı olduğu', 'Atomların birbirine değmesi', 'Evrenin kapalı bir kutu olması'], 'Aristoteles, ortamın direnci olmadan hareketin sonsuz hızda gerçekleşeceğini düşünür ve bunu saçma bulur. Bu yüzden boşluğu reddeder.'),
  ('Ainesidemos\'un şüpheciliği desteklemek için sıraladığı "on tropos" neyi gösterir?', 'Algının ve yargının koşullara göre değiştiğini, bu yüzden yargıyı askıya almak gerektiğini', ['Tanrı\'nın varlığına ilişkin on ayrı kanıtı ve bunların doğruluğunu göstermek', 'On ahlaki erdemi', 'Evrenin on katmanını'], 'Ainesidemos\'un tropları, farklı canlılar ve kişiler için aynı şeyin farklı göründüğünü anlatan türden örnekler içerir. Bu görecelik yargının askıya alınmasını gerektirir.'),
  ('Agrippa\'ya atfedilen "beş trop" içinde "diallelus" (döngüsel kanıtlama) neyi eleştirir?', 'Bir iddianın kanıtını yine o iddiaya dayandırmayı', ['Yalnızca duyulara güvenmeyi ve aklı kesin bilgi kaynağı olarak görmeyi, duyuları ise yok saymayı', 'Yaşamın kısalığını', 'Atomların bölünmezliğini'], 'Döngüsel kanıtlamada A, B ile kanıtlanır; B ise A\'ya dayanır. Septikler bunu bilginin temelsiz kaldığını göstermek için kullanır.'),
  ('Cicero\'nun felsefede benimsediği tutum hangisine en yakındır?', 'Akademi şüpheciliğine yakın, ama farklı okullardan yararlanan eklektik', ['Epikuros\'un bahçesi gibi tek bir okula bağlı, katı ve dogmatik, hiçbir şeyden ödün vermeyen', 'Saf Stoacılık', 'Saf Platonculuk'], 'Cicero Akademia\'nın olasılıkçı şüpheciliğine yakındı, ama Stoa, Platon ve Aristoteles\'ten seçerek yararlanırdı.'),
  ('Yeni Platoncu Proklos\'un Orta Çağ düşüncesine etkisini en iyi hangisi açıklar?', 'Platon\'un ve Plotinos\'un sistemini düzenleyip Hristiyan ve İslam düşünürlerine ulaşan bir metafizik bıraktı', ['Aristoteles\'in kıyas kuramını geliştirip kıyas kalıplarını bulması ve Orta Çağ mantık okullarını kurması', 'Atomculuğu Roma\'da yaydı', 'Skolastik yöntemi bulup üniversiteleri kurdu'], 'Proklos\'un "Teolojinin Öğeleri" sistemli bir Yeni Platoncu anlatımdı. Arapça ve Latince çevirilerle ve "Kitabü\'l-Hayr" gibi uyarlamalarla Orta Çağ\'a ulaştı.'),
  ('Yahudi düşünür Philon\'un felsefe tarihindeki özgün katkısı nedir?', 'Kutsal metni Yunan felsefesiyle alegorik yoldan yorumlayıp Logos kavramını dine taşıması', ['Evreni yalnızca atomlar ve boşlukla açıklayıp Yahudi kutsal metnini mantık kuralları dışında bırakması', 'Devleti ideal olarak tanımlaması', 'Kıyas kuramını bulması'], 'İskenderiyeli Philon, Tevrat\'ı Platoncu ve Stoacı kavramlarla yorumlayarak vahiy ile felsefeyi uzlaştırmaya çalıştı. Bu yöntem sonraki Hristiyan ve İslam düşünürlerini etkiledi.'),
  ('Apologist Justinus\'un (Şehit Justinus) Yunan felsefesine bakışı nasıldır?', 'Hakikatin tohumlarının (logos spermatikos) felsefede de bulunduğunu savunup felsefeyi Hristiyanlığa hazırlık sayar', ['Felsefenin tümüyle şeytani bir icat olduğunu söyleyip Sokrates\'in sapkınlıkla suçlanmayı hak ettiğini öne sürer', 'Platon\'un Hristiyan olduğunu kanıtlar', 'Yalnız Stoacılığı doğru bulur'], 'Justinus, Sokrates ve Herakleitos gibilerinin kısmen logosa uygun yaşadığını söyler ve felsefeyi doğru bilginin bir öncülü olarak görür.'),
  ('Orta Çağ\'da "apofatik teoloji" Tanrı\'yı nasıl anlatır?', 'Tanrı\'nın ne olmadığını söyleyerek, insan dilinin yetersizliğini vurgulayarak', ['Tanrı\'ya sürekli olumlu nitelikler sayarak, onu insan diliyle eksiksiz biçimde betimleyerek', 'Tanrı\'nın doğa yasalarıyla özdeş olduğunu söyleyerek', 'Tanrı\'yı yalnız tarihsel olaylarla tanımlayarak'], 'Apofatik yaklaşım, Tanrı\'nın sonsuzluğu karşısında dilin yetersiz olduğunu savunur. Bu yüzden Tanrı için yapılan her olumlu ifade yetersiz sayılır.'),
  ('Klemens (İskenderiyeli) Yunan felsefesini Hristiyanlık içinde nasıl konumlandırır?', 'Felsefeyi Yunanlara verilmiş, Hristiyanlığa hazırlayan bir eğitim aracı sayar', ['Felsefeyi sapkınlık sayıp tümden reddederek yalnız vahye bağlı kalınması gerektiğini söyler', 'Felsefeyi tek hakikat sayar', 'Yunan felsefesini yok eder'], 'Klemens felsefenin Yunanlar için Yasa\'nın Yahudiler için olduğu gibi Mesih\'e götüren bir öğretmen olduğunu savunur.'),
  ('Yeni Platonculuğun Iamblikhos\'a ait yönü olan "teurji" neyi anlatır?', 'Ritüeller ve törenler aracılığıyla tanrısal alanla bağ kurma uygulamasını', ['Yalnızca kıyas kalıplarını sınıflayan, ritüelleri ve ayinleri dışlayan bir mantık biçimini', 'Matematiksel yöntemi', 'Atomların hareketini'], 'Iamblikhos, Plotinos\'tan farklı olarak ruhun yükselmesinde ayinlere ve ritüellere büyük önem verdi. Bu yöne teurji denir.'),
  ('Aşırı gerçekçi (realist) Guillaume de Champeaux\'ya göre evrenseller nasıl var olur?', 'Bireylerden bağımsız ve onlardan önce gerçek varlıklar olarak', ['Yalnızca sözcüklerin sesi olarak, bireylerin ardından konuşma sırasında', 'Yalnızca bireylerin zihinsel soyutlaması olarak', 'Tanrı\'nın yarattığı bireyler olarak'], 'Gerçekçi görüş Platoncu geleneğe yakındır ve evrensellere bireylerden önce, gerçek varlık tanır. Nominalizm ise tersini söyler.'),
  ('Abelard\'ın evrenseller konusundaki çözümü olarak bilinen yaklaşım hangisidir?', 'Kavramcılık: evrenseller, bireylerin ortak yönlerinden zihnin oluşturduğu kavramlardır', ['Aşırı gerçekçilik: evrenseller bireylerden önce var olan tek gerçek varlıklardır ve bireyler yanılsamadır', 'Katı nominalizm', 'İdea kuramının aynen kabulü'], 'Abelard evrenselleri yalnızca ad saymaz; bireylerdeki benzerliklerden akıl yoluyla çıkarılan kavramlar sayar. Bu yaklaşım orta bir yol sunar.'),
  ('Gaunilo\'nun Anselmus\'un ontolojik kanıtına yönelttiği "kayıp ada" itirazı neyi gösterir?', 'Aynı mantıkla her mükemmel şeyin varlığı çıkarılabilir, bu da kanıtı geçersiz kılar', ['Tanrı\'nın hiç var olmadığını ve ontolojik kanıtın tümüyle doğru olduğunu, mükemmel adanın da gerçekten bulunduğunu', 'Adaların Tanrı olduğunu', 'Anselmus\'un hiç kanıt sunmadığını'], 'Gaunilo kusursuz bir adanın düşünülmesinin onun varlığını kanıtlamadığını belirtti. Anselmus buna Tanrı\'nın benzersizliğiyle yanıt verdi.'),
  ('Siger of Brabant gibi "Latin İbn Rüşdçüleri"ne yöneltilen başlıca suçlama nedir?', 'Felsefede doğru olanla inançta doğru olanın birbirine zıt olabileceğini ileri sürdükleri', ['Felsefeyi tümüyle yasakladıkları ve akıl yürütmenin dinsel konulara uygulanamayacağını söyledikleri', 'Atomculuğu savundukları', 'Tanrı\'nın tek olduğunu reddettikleri'], 'Kilise bu düşünürlerin akıl ve imanın iki ayrı hakikat verdiğini söylediğini düşünüyordu. Bu yüzden Paris\'te kınandılar.'),
  ('Bonaventura\'nın düşüncesi Aquinas\'ınkinden hangi bakımdan ayrılır?', 'Augustinusçu, mistik yönü ağır basıp Aristoteles\'e kuşkuyla baktı', ['Aristoteles\'i sınırsız biçimde benimseyip akla bütün alanlarda mutlak üstünlük tanıdı', 'Felsefeyi tamamen dışladı', 'Atomculuğu savundu'], 'Fransisken Bonaventura aklın amacını Tanrı\'ya ruhun yükselişi sayar, "Ruhun Tanrı\'ya Yolculuğu" adlı eserinde bu yolu betimler.'),
  ('Duns Scotus\'un "haecceitas" kavramı neyi anlatır?', 'Bir bireyi tür içinde benzersiz kılan tekillik ilkesini', ['Tanrı\'nın sonsuzluğunu ve bütün varlıkları kapsayan evrensel özü, yani maddeden bağımsız', 'Maddenin atomlarını', 'Mantık kıyasını'], 'Haecceitas ("buluk") bir şeyi aynı türdeki diğerlerinden ayıran bireysel özelliktir. Scotus bireyselliği Aquinas\'tan farklı biçimde temellendirir.'),
  ('Duns Scotus\'un irade ve akıl ilişkisindeki görüşü Aquinas\'tan nasıl ayrılır?', 'İradeyi akıldan üstün tutar', ['Aklı iradeden üstün tutar', 'İradenin varlığını reddeder', 'İkisinin aynı şey olduğunu söyler'], 'Scotus iradenin akıldan özgür ve üstün olduğunu savunan bir "iradeci" çizgiyi temsil eder. Bu yönü Aquinas\'ın akılcılığıyla karşıtlık oluşturur.'),
  ('Ockham\'ın mantık ve dil anlayışında "terim" kavramı hangi sonuca götürür?', 'Genel terimler yalnızca zihinsel ya da dilsel işaretlerdir', ['Genel terimler bireylerden önce var olan gerçek varlıklardır', 'Bütün terimler anlamsızdır', 'Her terim tek bir Tanrı\'yı anlatır'], 'Ockham nominalisttir: "insan" gibi ortak adlar bireyleri gösteren işaretlerdir, onlara karşılık gelen ayrı evrensel gerçeklikler yoktur.'),
  ('Ockham\'ın "via moderna" olarak anılan yeni yolu ile eski yol (via antiqua) arasındaki temel fark nedir?', 'Evrenselleri gerçek varlık saymayan nominalist yaklaşım ile gerçekçi yaklaşım arasındaki fark', ['Eski yolun Hristiyan, yeni yolun Müslüman düşünürlerce izlenmesi ve iki yolun farklı dinlere ait olması', 'Eski yolun matematiğe, yeni yolun şiire dayanması', 'Eski yolun Latince, yeni yolun Yunanca kullanması'], 'Via moderna nominalizm ve terim mantığına dayanırken via antiqua Aquinas ve Scotus gibi gerçekçi düşünürlerin yolunu izliyordu.'),
  ('Ockham\'a göre Tanrı\'nın varlığı ve sıfatları konusunda akıl ne kadar güvenilirdir?', 'Aklın kesin kanıt sunması zordur', ['Aklın tüm kanıtları eksiksiz sunabildiği', 'Duyuların her şeyi kanıtlayabildiği', 'Matematikle ispatın yeterli olduğu'], 'Ockham Aquinas\'ın kanıtlarının çoğunun kesin sonuç vermediğini düşünür. Bu, akıl ile inanç alanlarını birbirinden uzaklaştırır.'),
  ('Nicole Oresme Dünya\'nın dönüşü konusunda ne yapmıştır?', 'Dünya\'nın dönebileceğini savunan argümanlar geliştirip bunları inanç gerekçesiyle sonunda reddetmiştir', ['Dünya\'nın hareketsiz olduğunu deneyle kanıtlamış ve gök cisimlerinin dönüşünü bir yanılsama saymıştır', 'Güneşin merkez olduğunu ispatlamıştır', 'Hiçbir gök cismi hakkında yazmamıştır'], 'Oresme, gökyüzünün dönüşünün yerine Dünya\'nın dönmesinin aynı görüntüleri vereceğini gösterdi, ama sonunda dinsel gerekçelerle Dünya\'nın duruyor olması görüşünü benimsedi.'),
  ('Philoponus\'un Aristoteles\'in düşen cisimler kuramına yönelttiği eleştiri neyi öne sürer?', 'Cisimlerin ağırlığına göre düşme hızının orantılı biçimde farklı olmadığını', ['Cisimlerin hiç düşmediğini, yalnızca gökyüzünde döndüklerini ve ağırlığın bir etkisi olmadığını', 'Cisimlerin yalnız ateşle hareket ettiğini', 'Gök cisimlerinin düz çizgide hareket ettiğini'], 'İskenderiyeli Ioannes Philoponus, ağırlıkla hızın doğru orantılı olduğu görüşünü sorguladı. Fırlatılan cisimler için impetus benzeri bir güç düşünen ilk eleştirmenlerdendir.'),
  ('Raymond Lull\'un "Ars Magna" adlı çalışması neye öncülük eder?', 'Kavramların mekanik biçimde birleştirilerek sonuç üretilmesi fikrine', ['Atom kuramına ve maddenin bölünmez parçacıklardan oluştuğu düşüncesine, sonsuz bölünmeyle çelişkili biçimde', 'Gök mekaniğine', 'Roman türüne'], 'Lull, daire biçiminde dönen kavram çarklarını kullanarak doğruları üretebileceğini söyledi. Bu, sonradan Leibniz\'in mantıksal hesap düşüncesini esinleyen bir fikirdir.'),
  ('Meister Eckhart\'ın mistisizminde "ruhun kıvılcımı" neyi ifade eder?', 'İnsan ruhunda Tanrı\'yla doğrudan birleşmeye yarayan ilahi öğe', ['Evrenin ilk atomu ve bütün maddenin kendisinden doğduğu temel parçacık, ruhla ilgisiz', 'Yıldızların ışığı', 'Bedenin ateşi'], 'Eckhart\'a göre ruhun derininde Tanrı\'dan gelen bir kıvılcım vardır; insan kendinden soyunarak Tanrı\'yla birleşir. Eserleri 1329\'da kınandı.'),
  ('Nicolaus Cusanus\'un "De docta ignorantia" adlı eserinin ana fikri nedir?', 'Sonsuz olan Tanrı\'ya yaklaşırken insan bilgisinin sınırlarını bilmenin en yüksek bilgi olması', ['Bilgeliğin yalnızca ansiklopedi okumakla ve bütün bilimleri ezberleyerek kazanıldığı, insan bilgisinin sınırsız olduğu', 'Okuma yazma bilmeyenlerin bilgisiz olduğu', 'Aristoteles mantığının her şeyi çözdüğü'], '"Bilgili cehalet", sonsuzu sonlu akılla kavrayamayacağımızı bilmeyi anlatır. Cusanus bu eserde zıtların birliğini (coincidentia oppositorum) de işler.'),
  ('Cusanus\'un evrenin merkezi hakkındaki düşüncesi hangisidir?', 'Evrenin merkezi her yerde, çevresi hiçbir yerdedir', ['Dünya evrenin tek ve sabit merkezidir, çevresi ise gök küresi ile sınırlandırılmıştır', 'Güneş evrenin merkezidir', 'Merkez, Ay\'dadır'], 'Cusanus evreni sonsuz ve merkezsiz düşünerek Dünya\'yı ayrıcalıklı konumundan çıkardı. Bu görüş Kopernik öncesi kozmolojik düşünceyi etkiledi.'),
  ('Dante\'nin "Monarchia" adlı eserindeki temel savı nedir?', 'Dünya barışı için evrensel bir imparatorluk gerekir ve imparatorluk yetkisi doğrudan Tanrı\'dan gelir, papadan değil', ['Papa tüm dünyayı yönetmeli ve imparatorlar yetkilerini yalnızca papadan almalıdır, çünkü ruhani yetki üstündür', 'Her kent bağımsız olmalıdır', 'Krallar halk tarafından seçilmelidir'], 'Dante, imparator ile papanın ayrı alanlara sahip olduğunu, imparatorun yetkisinin papadan bağımsız biçimde Tanrı\'dan geldiğini savunmuştur.'),
  ('Gemistos Plethon\'un 1438-39 Floransa Konsili\'ne katılması hangi sonuca yol açmıştır?', 'İtalya\'da Platon çalışmalarının ve Platon Akademisi düşüncesinin canlanmasına', ['Aristoteles\'in yasaklanmasına ve bütün üniversitelerde felsefe eğitiminin durdurulmasına', 'Skolastik yöntemin sona ermesine', 'Üniversitelerin kapanmasına'], 'Bizanslı Plethon Floransa\'da Platon\'u anlatarak Cosimo de\' Medici\'yi etkiledi. Bu, sonradan Marsilio Ficino\'nun Platon Akademisi\'nin kurulmasında rol oynadı.'),
  ('Yuhanna Damaskenos\'un "Bilginin Kaynağı" adlı eseri neyi yapmıştır?', 'Yunan felsefesi ve kilise babalarının düşüncelerini sistemli bir Hristiyan öğreti halinde toplamıştır', ['Atom kuramını, evrenin sonsuz sayıdaki atomlardan oluştuğu görüşünü sistemli biçimde ele almıştır', 'Roma hukukunu özetlemiştir', 'Gök mekaniğini açıklamıştır'], 'Damaskenos, Doğu Hristiyan düşüncesini sistemleştirdi. Eserin bölümleri Latinceye çevrilerek Batı skolastiğini de etkiledi.'),
  ('Maximos Confessor\'un Bizans teolojisine etkisi için hangisi doğrudur?', 'Yunan felsefesinin kavramlarını Hristiyan mistik teolojiyle birleştirdi', ['Skolastik yöntemi kurdu ve Aristoteles mantığını Hristiyan teolojisine uyguladı, Platon\'u dışladı', 'Atomculuk öğretti', 'Üniversiteleri kurdu'], '7. yüzyılın bu düşünürü Neoplatonik ve Hristiyan düşünceyi birleştirerek sonraki Doğu Hristiyan düşüncesini etkiledi.'),
  ('Bizans İmparatorluğu\'nda felsefe ve bilimin sürdürülmesi Avrupa\'da hangi sonucu doğurmuştur?', 'Yunan metinlerinin korunup sonradan Rönesans\'ta İtalya\'ya aktarılması', ['Hiçbir sonuç doğurmamış, Yunan metinleri yok olmuş ve Batı onları yüzyıllar sonra yeniden yazmak zorunda kalmıştır', 'Bütün metinlerin yok olması', 'Latin Batı\'nın Yunanca öğrenmeyi bırakması'], 'Bizans bilginleri Yunanca metinleri kopyalayıp korudu. 15. yüzyılda İstanbul\'dan İtalya\'ya gelen bilginler bu metinleri Rönesans\'a taşıdı.'),
  ('Bessarion\'un Rönesans Avrupası\'ndaki işlevi nedir?', 'Bizanslı bir bilgin olarak Yunan metinlerini İtalya\'ya taşıyıp Platon-Aristoteles tartışmasını sürdürmesi', ['Bir mantık kuramı geliştirip skolastik yöntemin tartışma kurallarını belirleyen bir yönetmelik hazırlaması', 'Bir ordu yönetmesi', 'Skolastik yöntemi geliştirmesi'], 'Kardinal Bessarion değerli Yunanca el yazmalarını Venedik\'e bağışlayarak Marciana Kütüphanesi\'nin çekirdeğini oluşturdu.'),
  ('İslam felsefesinin doğuşunda aşağıdakilerden hangisi etkili olmamıştır?', 'Matbaanın icadı', ['Çeviri faaliyetleri', 'Abbasi halifelerinin bilim desteği', 'Kelam tartışmaları'], 'Matbaa Avrupa\'da 15. yüzyılda yaygınlaşmıştır. İslam felsefesinin doğuşunda çeviri hareketi, devlet desteği ve kelamın yarattığı tartışma ortamı etkiliydi.'),
  ('Ya\'kub b. İshak el-Kindi\'nin felsefeyi tanımlarken öne çıkardığı yaklaşım aşağıdakilerden hangisidir?', 'Felsefe, hakikatin kendisini arar; bu nedenle farklı kültürlerden gelen doğrulara açık olmak gerekir', ['Felsefe yalnız Yunanlılara özgüdür ve başka kültürlerin katkısı yoktur', 'Felsefe inanca düşmandır ve terk edilmelidir', 'Felsefe yalnız tıbbın bir dalıdır'], 'Kindi, "İlk Felsefe Üzerine" eserinde hakikatin nereden gelirse gelsin kabul edilmesi gerektiğini söyler. Bu, Yunan mirasının benimsenmesine meşruiyet kazandırdı.'),
  ('Kindi\'ye göre Tanrı\'nın ayırt edici özelliği olarak "gerçek bir" (el-vâhid el-hak) kavramı neyi anlatır?', 'Hiçbir çokluk ve parçalanma kabul etmeyen mutlak birlik', ['Evrenin tüm parçalarının toplamı olan sayısal birlik, parçalardan oluşan bütün', 'Sayıların ilk elemanı olan bir', 'Maddenin en küçük parçası'], 'Kindi, sayısal bir olan ile mutlak olarak bir olan arasında ayrım yapar. Tanrı çokluğu bulunmayan gerçek birdir; her şey ondan türer.'),
  ('Razi\'nin felsefede akla verdiği yer hangisini en iyi yansıtır?', 'Aklı Tanrı\'nın insanlara verdiği en büyük armağan sayıp her konuda başlıca ölçüt kabul etmesi', ['Aklı vahyin altına koyması', 'Aklı duyguların hizmetkârı sayması', 'Aklı tümüyle dışlaması'], 'Razi aklı insanın hakikate ulaşma ve yaşamını düzenleme gücü olarak görür. Hekimlik ve felsefe birbirini tamamlar.'),
  ('İhvan-ı Safa\'nın eserlerinin yazılış amacı nedir?', 'Felsefe ve din arasında uyum kurup bilgiyi arınma yolu olarak yaymak', ['Askerleri eğitmek', 'Ticaret yapmak', 'Siyasi bir parti kurmak'], 'Topluluk, hakikatin felsefe ve vahiy ile birlikte bulunabileceğine inanıyor; risaleler ruhun arınmasına yardımcı olmayı amaçlıyordu.'),
  ('Farabi\'ye göre erdemli şehrin yönetimi ile insan bedeni arasında nasıl bir benzerlik kurulur?', 'Şehir, kalbin yönettiği organlardan oluşan bir beden gibi tek bir başkan etrafında düzenlenir', ['Şehir, hiç başkanı olmayan bir bedendir', 'Şehir yalnızca ellerden oluşur', 'Şehir yalnızca bir ağızdan ibarettir'], 'Farabi şehirdeki yöneticiyi kalbe benzetir; diğer organlar gibi yurttaşlar, ortak amaca yönelir. Bu benzetme tek başkan düzenini savunur.'),
  ('Gazali\'nin "Makasıdü\'l-Felasife" adlı eseri neye hizmet eder?', 'Filozofların görüşlerini anlaşılır biçimde anlatıp sonra Tehafüt\'te eleştirmeye zemin hazırlar', ['Felsefeyi tümüyle yasaklamaya', 'Siyasi fetva vermeye', 'Hekimlik kuralları koymaya'], 'Gazali bu kitapta İbn Sina\'nın düşüncelerini özetler; Tehafüt\'te ise bunları eleştirir. Latinceye çevrilince Gazali bir filozof sanıldı.'),
  ('Gazali Tehafüt\'te filozofların Tanrı\'nın "tikelleri bilmemesi" görüşüne neden karşı çıkar?', 'Bu görüşün Tanrı\'nın bilgisini sınırlandırdığını ve dinle çeliştiğini düşündüğü için', ['Tanrı\'nın bilgisi olmadığını söylediği için', 'Tanrı\'yı yalnız insanla sınırladığı için', 'Filozofların hiç bilgi sahibi olmadığı için'], 'Filozoflar Tanrı\'nın değişen tikelleri değil yalnız tümelleri bildiğini söyler. Gazali buna Tanrı\'nın her şeyi bildiği ilkesiyle itiraz eder.'),
  ('İbn Bacce\'nin "Yalnız Yaşayanın Tedbiri" adlı eseri hangi sorunu işler?', 'Kusurlu bir toplumda yaşayan filozofun yalnızlaşarak akıl yoluyla yükselmesi', ['Askeri strateji', 'Ticaret ahlakı', 'Tarım teknikleri'], 'Zaragozalı İbn Bacce, filozofun düzensiz bir toplumdan uzak durarak ilahi akılla birleşmeyi hedeflemesi gerektiğini savunur.'),
  ('Latin skolastiklerin İbn Rüşd\'e atfettiği "aklın birliği" (monopsişizm) öğretisi neyi söyler?', 'Bütün insanlarda faal aklın tek ve ortak olduğunu', ['Her insanın aklının ayrı ve ölümlü olduğunu, bedenle yok olduğunu', 'Aklın yalnız Tanrı\'ya ait olduğunu', 'Aklın hiç bulunmadığını'], 'İbn Rüşd\'e atfedilen bu görüşe göre maddi olmayan akıl bütün insanlar için tektir. Latin skolastikler bunu inanç yönünden tehlikeli bulup eleştirdi.'),
  ('Sühreverdi\'nin "Maktul" lakabı neden kullanılır?', 'Halep\'te Selahaddin Eyyubi döneminde fikirleri nedeniyle idam edilmesi nedeniyle', ['Savaşta ölmesi nedeniyle', 'Zehirlenmesi nedeniyle', 'Doğal ölümü nedeniyle'], 'Sühreverdi 1191\'de Halep\'te öldürüldü; bu yüzden "el-Maktul" (öldürülen) diye anılır.'),
  ('Mutezile\'nin kurucusu olarak anılan Vasıl b. Ata\'nın Hasan el-Basri\'den ayrılmasına yol açan görüş nedir?', 'Büyük günah işleyenin ne mümin ne kâfir, iki konum arasında bir yerde olduğu', ['İnsanın hiç özgür olmadığı', 'Tanrı\'nın yoksunluğu', 'Akılın değersizliği'], 'Büyük günah işleyenin hükmü konusunda Hasan el-Basri\'den ayrılan Vasıl\'ın grubuna "ayrılanlar" anlamına gelen Mutezile denmiştir.'),
  ('Eş\'ari\'nin Mutezile\'den ayrılarak geliştirdiği kelam ekolünün insan fiillerine ilişkin açıklaması hangisidir?', 'Fiili Tanrı yaratır, insan onu "kesb" eder', ['İnsan fiillerinin tamamen insana ait olduğu', 'İnsan fiilinin olmadığı', 'Fiillerin tesadüfen gerçekleştiği'], 'Eş\'ari\'nin kesb öğretisi, fiilin yaratıcısını Tanrı sayar ama insana bu fiili sahiplenme sorumluluğu verir. Böylece cebir ile kader arasında bir yol arar.'),
  ('Cebriye mezhebinin insan fiilleri hakkındaki temel görüşü nedir?', 'İnsan bütün fiillerinde zorunlu olarak Tanrı\'ya bağlıdır, iradesi yoktur', ['İnsan her şeyde tam özgürdür', 'İnsan fiilleri rastlantıdır', 'Fiillerin yaratıcısı yıldızlardır'], 'Cebriye insanın tüm eylemlerinin zorunlu olduğunu, Tanrı\'nın onları belirlediğini savunur. Kaderiye ise insan özgürlüğünü vurgular.'),
  ('Kelam geleneğinde "cevher-i ferd" (bölünmez parça) görüşü hangi düşünceyle ilişkilidir?', 'Atomculukla; evrenin bölünemeyen parçacıklardan oluştuğu görüşüyle', ['Maddenin sonsuz bölünebilirliğiyle', 'Hareketin yanılsamasıyla', 'Platon\'un idealar kuramıyla'], 'Kelamcılar Tanrı\'nın evreni sürekli yeniden yarattığı fikrini desteklemek için atom ve araz öğretisini kullandı.'),
  ('Mutezile ile Eş\'ariyye arasındaki temel ayrım hangi tartışmada belirginleşir?', 'Akıl ile vahyin ağırlığı ve insan iradesinin sınırları', ['Namazın kılınış biçimi ve hac yolculuğunun hükümleri üzerine', 'Hac yolculuğu', 'Zekâtın miktarı'], 'Mutezile akla ve insan özgürlüğüne daha çok yer verirken Eş\'ariyye Tanrı\'nın mutlak iradesini ve vahyi vurgular.'),
  ('Me\'mun döneminde yaşanan "Mihne" olayı neyle ilgilidir?', 'Kur\'an\'ın yaratılmış olup olmadığı tartışması ve bilginlerin sorgulanması', ['Vergi sistemi', 'Yeni bir şehrin kurulması', 'Hacıların güvenliği'], 'Halife Me\'mun\'un Mutezile görüşünü devlet görüşü kılması üzerine Ahmed b. Hanbel gibi bilginler sorguya çekildi.'),
  ('İbn Miskeveyh\'in "Tehzibü\'l-Ahlak" adlı eserinde erdem nasıl tanımlanır?', 'Aşırı uçlar arasında orta yol', ['Yalnız ibadet, uç noktada ibadet', 'Yalnız servet', 'Yalnız güç'], 'Miskeveyh Aristoteles\'in orta yol anlayışını alıp ruhun akıl, öfke ve şehvet güçlerine bağlı dört erdem (hikmet, şecaat, iffet, adalet) sıralar.'),
  ('İbn Heysem\'in "Kitabü\'l-Menazır" adlı eserinde görme olayı nasıl açıklanır?', 'Işık cisimlerden gözümüze gelir', ['Işık gözümüzden çıkıp cisme gider', 'Görme yalnız ruhta olur', 'Görme yalnız Güneş sayesindedir'], 'İbn Heysem deneyle Eski Yunan\'daki göz ışınları görüşünü çürüttü ve ışığın cismin yüzeyinden göze geldiğini savundu. Bu yüzden optiğin babası sayılır.'),
  ('İbn Heysem\'in bilim yönteminde öne çıkan özellik nedir?', 'Hipotezi deneyle sınama ve gözleme dayanma', ['Yalnız otoriteye güvenme ve kitapları tekrar etme', 'Yalnız kehanete güvenme', 'Yalnız kıyasla ispat'], 'İbn Heysem\'e atfedilen yaklaşım, kuramların deneyle denetlenmesi gerektiğini savunur. Bu, sonraki Avrupa deneysel optiğini etkiledi.'),
  ('Harezmi\'nin Orta Çağ düşüncesine katkısı için hangisi doğrudur?', 'Cebir kitabıyla cebiri ayrı bir matematik dalı olarak sistemleştirmiştir', ['Mantığı kurmuştur', 'Atomu keşfetmiştir', 'Teleskopu icat etmiştir'], 'Harezmi\'nin "el-Cebr ve\'l-Mukabele" kitabı cebir teriminin kaynağıdır. "Algoritma" sözcüğü de onun adından türemiştir.'),
  ('Xunzi (Hsün Tzu), Mencius\'tan farklı olarak insan doğası hakkında ne söyler?', 'İnsan doğası bencildir ve ancak eğitim ve törelerle iyileştirilir', ['İnsan doğası özünde iyidir', 'İnsan doğası ruhsaldır ve tanrısaldır', 'İnsan doğası hiç değişmez'], 'Xunzi, doğal eğilimlerin çatışma doğurduğunu, bu yüzden "li" (töre) ve eğitimle terbiye gerektiğini savunur. Bu görüş Konfüçyüsçülüğün gerçekçi kanadını oluşturur.'),
  ('Mozi\'nin (Mo Tzu) "jian ai" (evrensel sevgi) öğretisi neyi savunur?', 'Herkese ayrım gözetmeden eşit sevgi göstermeyi, bu yolla savaşı önlemeyi', ['Yalnız aile üyelerini sevmeyi', 'Yalnız hükümdarı sevmeyi', 'Sevgiyi bütünüyle reddetmeyi'], 'Mozi, Konfüçyüsçü kademeli sevgiye karşı çıkarak herkese eşit ilgi gösterilmesini ve bunun yararlı olacağını söyledi; savaşa karşıdır.'),
  ('Daoculukta doğaya uygun yaşamın simgesi olarak "esneyen su"nun kullanılması neyi anlatır?', 'Yumuşak ve esnek olanın sert olandan daha üstün ve dayanıklı olabileceğini', ['Suyun yalnız içilebilir olduğunu', 'Sert olanın hep üstün geldiğini', 'Suyun kirli olduğunu'], 'Lao Zi suyu en yumuşak ama en güçlü şey olarak betimler; güçlü görünenin değil esneyenin kalıcı olacağını anlatır.'),
  ('Çarvaka (Lokayata) okulunun bilgi ve varlık görüşü nedir?', 'Yalnız duyu algısını geçerli bilgi sayıp maddeyi tek gerçeklik kabul eder', ['Ruhun ölümsüz olduğunu savunur', 'Tanrı\'nın varlığını kanıtlamaya çalışır', 'Karma öğretisini savunur'], 'Çarvakalar çıkarım ve kutsal metni reddederek yalnızca algıyı güvenilir bilgi kabul etti; ruh ve ahiret düşüncesine karşı çıktı.'),
  ('Nagarjuna\'nın "sunyata" (boşluk) öğretisi neyi söyler?', 'Hiçbir şeyin kendi başına sabit bir özü olmadığını, her şeyin karşılıklı bağımlı olduğunu', ['Evrenin boş olduğu için var olmadığını', 'Tanrının yokluğunu', 'Ruhun sonsuzluğunu'], 'Madhyamaka okulunun kurucusu Nagarjuna, varlıkların bağımlı doğduğunu ve özsel bir doğaları olmadığını söyler; bu boşluk "hiçlik" değildir.'),
  ('Hint toplum düzeninde "varna" (kast) sistemini felsefi olarak temellendiren metinler daha çok hangi geleneğe aittir?', 'Brahmanik (Vedik) gelenek', ['Budist gelenek, Buda öğretisi', 'Jain gelenek', 'Çarvaka geleneği'], 'Brahmanik gelenek toplumu dört varna\'ya ayırır. Buda ve Mahavira bu doğuştan ayrıcalığa karşı çıktı.'),
  ('Maimonides\'in Tanrı\'yı anlatma yöntemi olarak savunduğu yol hangisidir?', 'Olumsuz sıfatlar yoluyla anlatım', ['Olumlu sıfatlarla tam ve eksiksiz tanımlama', 'Yalnızca mitlerle anlatım', 'Yalnızca sayılarla anlatım'], 'Maimonides Tanrı\'nın ne olmadığını söylemenin ona yaklaşmanın tek güvenli yolu olduğunu savunur. Bu, Pseudo-Dionysios\'a yakın bir olumsuz teoloji çizgisidir.'),
  ('Saadia Gaon\'un "İmanlar ve Kanaatler Kitabı"nın yazılış amacı nedir?', 'Akıl ile vahyin uyumunu göstererek Yahudi inancını akılcı biçimde temellendirmek', ['Yahudiliği tümden reddetmek', 'Mantık kurallarını Latinceye çevirmek', 'Tıp tarihi yazmak'], 'Saadia, Mutezile kelamından yararlanarak Yahudi inancının akılla savunulabileceğini göstermeye çalıştı.'),
  ('İbn Gabirol\'un (Avicebron) "Hayat Kaynağı" adlı eserinde öne çıkan görüş nedir?', 'Ruhsal varlıklar da dahil her şeyin madde ve formdan oluştuğu', ['Her şeyin yalnızca atomlardan oluştuğu', 'Maddenin hiçbir rolünün olmadığı', 'Evrenin ezeli olduğu'], 'İbn Gabirol, Yeni Platoncu bir bakışla madde-form çiftini bütün varlığa genişletir. Bu görüş Fransisken düşünürleri etkiledi.'),
  ('Yehuda Halevi\'nin "Kuzari" adlı eseri hangi çerçevede yazılmıştır?', 'Hazar kralı ile bir Yahudi bilgin, bir filozof, bir Hristiyan ve bir Müslüman arasında geçen bir diyalog biçiminde', ['Bir savaş günlüğü olarak', 'Bir şiir antolojisi olarak', 'Bir matematik kitabı olarak'], 'Kuzari, Hazar (Hazar Türkleri) hükümdarının din arayışı çerçevesinde geçer. Halevi felsefi akıl yürütmeden çok vahyin ve tarihsel deneyimin değerini savunur.'),
  ('Gersonides (Levi ben Gerson) ve Hasdai Crescas\'ın felsefe tarihindeki ortak yönü nedir?', 'Aristotelesçiliği eleştirel biçimde değerlendiren geç dönem Yahudi filozoflar olmaları', ['Atomcu olmaları', 'Platon karşıtı olmaları', 'Skolastik yöntemi başlatmaları'], 'İkisi de Aristoteles\'in kozmolojisini ve Maimonides\'in görüşlerini tartışıp eleştirdi. Crescas özellikle Aristoteles\'in boşluk ve sonsuzluk anlayışını reddetti.'),
  ('Philon\'dan Maimonides\'e uzanan Yahudi felsefesinin Hristiyan skolastiğine katkısı nedir?', 'Kutsal metnin felsefi yorumu ve Tanrı\'nın sıfatları konusundaki tartışmaları aktarması', ['Hiçbir katkısı olmaması', 'Yalnız hukuk kuralları aktarması', 'Yalnız takvim hesapları aktarması'], 'Maimonides ve İbn Gabirol gibi Yahudi düşünürlerin Latince çevirileri Aquinas ve Duns Scotus gibi skolastiklerce okundu.'),
  ('Empedokles\'in canlıların oluşumuna ilişkin spekülasyonunda hangi fikir bulunur?', 'Önce ayrı organlar oluştu, uygun biçimde birleşenler hayatta kaldı', ['Canlılar bir anda eksiksiz yaratıldı', 'Canlılar yalnızca ateşten doğdu', 'Canlılar tohumlarla gökten indi'], 'Empedokles\'e atfedilen anlatıya göre eşleşen organların uygun bileşimleri yaşamayı sürdürür. Bu, doğal seçilimi andıran erken bir görüştür.'),
  ('Platon\'un "Sofist" diyaloğunda Eleli Yabancı hangi sorunu çözer?', 'Yokluğun bir anlamda "başkalık" olarak var olduğunu göstererek yanlış söylemenin olanağını', ['Tanrıların sayısını', 'Devletin kuruluşunu', 'Evrenin yaşını'], 'Platon bu diyalogda Parmenides\'in "yokluk yoktur" tezine karşı "olmayan"ın "başka olan" anlamına geldiğini gösterir ve yanlış önermeleri mümkün kılar.'),
  ('Aristoteles\'e göre trajedi komedi ile karşılaştırıldığında hangi nitelikle ayrılır?', 'Trajedi, daha iyi ve ciddi kişilerin eylemini; komedi ise daha aşağı kişilerin gülünç yanlarını taklit eder', ['Trajedi yalnızca müzikle, komedi yalnızca dansla yapılır', 'Trajedi yalnızca düzyazıdır', 'İkisi arasında fark yoktur'], 'Poetika\'ya göre trajedi ciddi ve tam bir eylemin, komedi ise çirkin olmayan ama daha aşağı insanların gülünç yönlerinin taklidi olarak tanımlanır.'),
  ('Aquinas Anselmus\'un ontolojik kanıtını neden kabul etmez?', 'Tanrı\'nın özü bizce doğrudan bilinmez; varlığı yalnız etkilerinden çıkarsanabilir', ['Tanrı\'nın var olmadığını düşündüğü için', 'Anselmus\'u tanımadığı için', 'Mantığı reddettiği için'], 'Aquinas Tanrı\'nın varoluşunun kendi kendine apaçık olmadığını, ancak dünyadan hareketle sonradan (a posteriori) gösterilebileceğini savunur.'),
  ('Salisburyli John\'un "Policraticus" adlı eserinde tiranlık konusundaki görüşü nedir?', 'Adaletsiz, Tanrı yasasına aykırı yöneticiye direnmenin ve onu devirmenin meşru olabileceğini söyler', ['Her yöneticiye kayıtsız itaat gerekir', 'Tiranlık en iyi yönetimdir', 'Yöneticiler halkın kölesidir'], 'John, adil olmayan yöneticiyi tiran sayar ve bu konuda direniş düşüncesinin ilk ayrıntılı örneklerinden birini sunar.'),
  ('Orta Çağ siyaset düşüncesinde "iki kılıç kuramı" neyi anlatır?', 'Dünyevi ve ruhani yetkilerin ayrı iki kılıç olarak papa ve imparatorda bulunduğunu', ['Papa ile imparatorun aynı kişi olduğunu', 'Savaşta yalnız iki silah kullanılacağını', 'Kralların hiç yetkisi olmadığını'], 'Kuram, ruhani gücün kilisede, dünyevi gücün hükümdarda olduğunu söyler; ama hangisinin üstün olduğu uzun süre tartışılmıştır.'),
  ('Hümanist Erasmus\'un "Deliliğe Övgü"sü dışında Orta Çağ skolastiğine yönelttiği başlıca eleştiri nedir?', 'İncelikli ve sonuçsuz kavram tartışmalarına boğulması', ['Matematikle uğraşması ve geometriyi yeterince önemsememesi nedeniyle', 'Kitap yazmaması', 'Yalnızca şiirle ilgilenmesi'], 'Rönesans hümanistleri skolastiğin ince ayrımlarını gerçek yaşamla ilgisiz gördü ve klasik metinlere dönüşü savundu.'),
  ('Ockham\'ın Papa karşıtı yazılarında kullandığı hangi ilke, yönetimin sınırlandırılmasına katkı yapmıştır?', 'Papaların hata yapabileceği ve yetkinin sınırlı olduğu', ['Papaların hiç yanılmayacağı ve yetkilerinin sınırsız olduğu ilkesi', 'İmparatorun hiç yetkisi olmadığı', 'Halkın hiçbir hakkının olmadığı'], 'Ockham papanın yanılabileceğini ve dünyevi yetkisinin sınırlı olduğunu savundu; bu görüş sonraki anayasacılık düşüncesini etkiledi.'),
  ('Duns Scotus\'un "varlığın tek anlamlılığı" (univocity of being) öğretisi neyi söyler?', '"Varlık" sözcüğünün Tanrı ve yaratıklar için aynı anlamda kullanıldığı', ['Varlığın hiçbir anlamı olmadığı', 'Yalnız Tanrı\'nın var olduğu', 'Varlığın bir yanılsama olduğu'], 'Aquinas\'ın analojisine karşı Scotus, varlık kavramının hem Tanrı hem yaratılmışlar için ortak bir tek anlam taşıdığını söyler.'),
  ('Kindi\'nin Aristoteles\'ten ayrılarak savunduğu görüş hangisidir?', 'Âlemin zamanda yaratılmış olduğu, ezelî olmadığı', ['Âlemin ezelî olduğu, zamanın başlangıcı bulunmadığı ve yaratılmadığı görüşü', 'Âlemin hiç yaratılmadığı', 'Âlemin atomlardan kendiliğinden oluştuğu'], 'Kindi, evrenin ve zamanın sonlu olduğunu, Tanrı tarafından yoktan yaratıldığını söyleyerek Aristoteles\'in ezelî evren görüşüne karşı çıktı.'),
  ('İbn Rüşd\'e göre dinî metinlerde zahirî anlamla bağdaşmayan bir ifade akılla çelişirse ne yapılmalıdır?', 'Metin akla uygun olacak biçimde te\'vil (yorum) edilmelidir', ['Akıl terk edilmeli ve yalnızca zahirî anlam benimsenmelidir', 'Metin yok sayılmalıdır', 'Felsefe yasaklanmalıdır'], 'İbn Rüşd, Faslü\'l-Makal\'de kesin burhanla çelişen zahirî ifadenin, dilin kuralları içinde te\'vil edilebileceğini söyler.'),
  ('Fahreddin er-Razi\'nin kelam geleneğine katkısı nedir?', 'Kelamı felsefi kavramlarla birleştirip sonraki dönemin kelam-felsefe karışımı yöntemine öncülük etmesi', ['Kelamı terk edip felsefeye geçmesi', 'Mutezile\'yi kurması', 'Tıp eğitimini başlatması'], 'Fahreddin Razi, İbn Sina felsefesini eleştirirken kendi kelam sistemini onun terimleriyle yazdı; bu çizgiye "müteahhirin kelamı" denir.'),
  ('Hacı Bektaş Veli\'nin "dört kapı kırk makam" öğretisi neyi anlatır?', 'Şeriat, tarikat, marifet, hakikat kapılarının ruhsal gelişim basamakları olduğunu', ['Dört ayrı kentin yönetimini', 'Kırk kişilik bir askerî birliği', 'Dört mevsimin düzenini'], 'Bu anlayışa göre kişi dört kapıdan geçerek her birinde on makam kat eder ve olgunlaşır; Anadolu Alevi-Bektaşi öğretisinin temel kavramlarındandır.'),
  ('14. yüzyıla gelindiğinde İslam felsefesinin Doğu ve Batı İslam dünyasındaki seyri hakkında hangisi doğrudur?', 'Doğuda İbn Sina etkisi kelam ve işrakla birleşirken Endülüs\'te İbn Rüşd\'ün Aristotelesçi felsefesi yükselmiştir', ['Her yerde aynı biçimde Mutezilecilik egemendi', 'Felsefe hiçbir yerde yazılmadı', 'Yalnız Mısır\'da felsefe yapıldı'], 'Doğuda Gazali\'nin eleştirisi sonrasında felsefe kelam ve tasavvufla iç içe geçti; Endülüs\'te ise İbn Bacce, İbn Tufeyl ve İbn Rüşd akılcı çizgiyi sürdürdü.'),
  ('Sabit b. Kurra\'nın bilim tarihindeki önemi nedir?', 'Harran\'da yetişip Yunanca eserleri çevirmesi ve matematik ile astronomiye katkıları', ['Atomcu bir kuram kurması', 'Gazali\'nin hocası olması', 'Latince eser yazması'], 'Harranlı Sabiî Sabit b. Kurra, Arkhimedes ve Apollonios gibi yazarları Arapçaya çevirdi ve matematik ve astronomide özgün çalışmalar yaptı.'),
  ('İslam felsefesinin Orta Çağ Avrupası\'na ulaşmasında hangi yol belirleyici olmuştur?', 'Endülüs, Sicilya ve Toledo\'dan yapılan Arapça-Latince çeviriler', ['Matbaanın icadı', 'Haçlı Seferleri sırasında yazılan şiirler', 'Papa\'nın fermanları'], '12.-13. yüzyıllarda Arapça eserler Toledo, Sicilya ve Endülüs\'te Latinceye çevrildi; İbn Sina, İbn Rüşd ve Farabi bu yolla Latin Batı\'da tanındı.'),
  ('Thales "her şey sudandır", Pythagoras "her şey sayıdır" diyor. İki görüşün asıl ayrımı hangisidir?', 'Birinin ilkesi maddi bir öğe, ötekinin ilkesi biçimsel-matematiksel bir düzendir', ['İkisi de madde ilkesi seçmiştir', 'İkisi de tanrıyı ilke saymıştır', 'İkisi de ilkeyi reddetmiştir'], 'Su duyularla gözlenen bir madde, sayı ise soyut bir düzen ilkesidir. Böylece felsefe maddeci ve biçimci açıklamalar arasında dallanır.'),
  ('Tanrı kanıtlarından Anselmus\'unki ile Aquinas\'ınkiler arasındaki temel yöntem farkı nedir?', 'Anselmus\'unki kavramdan (a priori), Aquinas\'ınkiler deneyimlenen dünyadan (a posteriori) hareket eder', ['Anselmus\'unki dünyadan, Aquinas\'ınkiler kavramdan hareket eder', 'İkisi de yalnız vahye dayanır', 'İkisi de tümüyle matematiktir'], 'Ontolojik kanıt Tanrı kavramından varlığını çıkarır; Aquinas\'ın beş yolu ise doğada gözlenen hareket, neden, düzen gibi olgulara dayanır.'),
  ('Aquinas, Maimonides ve İbn Rüşd\'ün ortak noktası aşağıdakilerden hangisidir?', 'Üçünün de Aristoteles felsefesiyle kendi dinleri arasında uzlaşma aradığı', ['Üçünün de Platon\'u yasaklaması', 'Üçünün de aynı dini benimsemesi', 'Üçünün de felsefeyi reddetmesi'], 'Aquinas (Hristiyan), Maimonides (Yahudi) ve İbn Rüşd (Müslüman), vahiy ile akıl arasında bir uyum kurmaya çalışan Aristotelesçi düşünürlerdir.'),
  ('Kentin en iyi yönetim biçimi sorusunda Platon ile Aristoteles\'in yaklaşımı nasıl ayrışır?', 'Platon bilge filozof yönetimini savunur, Aristoteles karma ve ölçülü bir politeia\'yı öne çıkarır', ['İkisi de demokrasiyi savunur', 'İkisi de tiranlığı savunur', 'İkisi de hiçbir yönetimi önermez'], 'Platon "Devlet"te filozof krallığı ister; Aristoteles ise orta sınıfa dayanan, kuvvetler dengeli ve yasalarla sınırlı bir yönetimi daha uygulanabilir bulur.'),
  ('Platon ile Aristoteles\'in sanat görüşü karşılaştırıldığında hangisi doğrudur?', 'Platon taklidi gerçeklikten uzak sayıp eleştirirken Aristoteles taklidin öğretici ve arındırıcı değeri olduğunu savunur', ['İkisi de sanatı tümüyle yasaklar', 'İkisi de taklidin gerçeklikten uzak olduğunu söyler', 'İkisi de sanatı tanrısal ilham sayar'], 'Platon şairleri devletten uzaklaştırmak ister, Aristoteles ise trajedinin katharsis yoluyla yararlı olduğunu söyler.'),
  ('Epikuros\'un hazcılığı ile Kirene\'li Aristippos\'un hazcılığı arasındaki fark nedir?', 'Epikuros dinginlik ve acısızlığı, Aristippos anlık bedensel hazzı öne çıkarır', ['İkisi de bedensel hazzı yüceltir', 'İkisi de hazzı reddeder', 'İkisi de siyasete katılımı savunur'], 'Epikuros\'a göre en yüksek haz acı ve kaygının yokluğudur; Kireneliler ise o anki yoğun hazzı hedefler.'),
  ('Septik Pyrrhon ile Stoacı Zenon\'un ortak hedefi nedir?', 'Ruhsal dinginlik ve huzur', ['Siyasi iktidar ve güç elde etme', 'Servet birikimi', 'Bilimsel keşifler'], 'Septikler yargıyı askıya alarak, Stoacılar tutkulardan arınarak huzura ulaşmayı amaçlar; yollar farklıdır.'),
  ('Plotinos ile Platon arasındaki temel fark hangisidir?', 'Plotinos\'ta her şey Bir\'den taşar ve en üstte Bir vardır; Platon\'da en üstte İyi ideası ve demiurgos vardır', ['Plotinos materyalisttir', 'Platon maddeyi tek ilke sayar', 'İkisi arasında hiçbir ilişki yoktur'], 'Plotinos Platon\'u yeniden yorumladı: İyi\'nin de ötesinde Bir\'i kabul etti ve varlığı taşma süreciyle açıkladı.'),
  ('Farabi ile Gazali\'nin felsefeye tutumu nasıl karşılaştırılabilir?', 'Farabi felsefeyi yüceltir ve dinle uzlaştırır, Gazali filozofların bazı görüşlerini eleştirir', ['İkisi de felsefeyi tümüyle reddeder', 'İkisi de felsefeyi aynen kabul eder', 'Gazali felsefeyi baştan sona över'], 'Farabi vahiy ve aklı birbirine yakınlaştıran bir sistem kurdu; Gazali ise "Tehafüt"te filozofların bazı görüşlerini bilimsel ve dinsel gerekçelerle eleştirdi.'),
  ('İbn Sina ile İbn Rüşd\'ün felsefedeki konumu hangi seçenekte doğru karşılaştırılmıştır?', 'İbn Sina Yeni Platoncu etkileri taşıyan bir sistem kurmuş, İbn Rüşd ise Aristoteles\'e daha sadık kalmaya çalışmıştır', ['İkisi de Platon karşıtıdır', 'İbn Rüşd Yeni Platoncu, İbn Sina Aristotelesçi saftır', 'İkisi de atomcudur'], 'İbn Rüşd Aristoteles\'in öğretisinden sudur gibi sonradan eklenen fikirleri ayıklamaya çalıştı; İbn Sina ise Yeni Platoncu unsurları sistemine kattı.'),
  ('Platon\'un "Devlet"inde yönetici sınıfın "bilgelik", Aristoteles\'in etiğinde ise "phronesis" vurgulanması neyi gösterir?', 'İki filozofun da yönetim ve ahlak için akla dayalı bir erdemi merkeze koyduğunu', ['İkisinin de aklı reddettiğini', 'İkisinin de erdemi önemsemediğini', 'İkisinin de tanrılara dayandığını'], 'Platon\'da yöneticinin bilgeliği, Aristoteles\'te pratik bilgelik doğru eylemin temelidir; ikisinde de akıl ahlakın merkezindedir.'),
  ('Sofistlerin göreceliği ile Platon\'un idealar kuramı arasındaki temel karşıtlık nedir?', 'Sofistlerde doğru kişiye göre değişir, Platon\'da değişmeyen ve evrensel hakikat vardır', ['İkisi de her şeyin göreli olduğunu söyler', 'İkisi de duyuları hakikatin ölçütü sayar', 'İkisi de Parmenides\'e karşıdır'], 'Protagoras "insan ölçüdür" derken Platon duyulur dünyanın ötesinde ideaların nesnel hakikatini savunur.'),
  ('Demokritos ile Epikuros\'un atomculuğu arasındaki ayrım nedir?', 'Epikuros atom hareketine "sapma" ekleyerek özgür iradeye yer açar, Demokritos ise katı determinist kalır', ['İkisi de Platon\'a karşıdır', 'Demokritos özgür iradeyi savunur', 'Epikuros atomları reddeder'], 'Epikuros, Demokritos\'un kesin nedenselliğinden kurtulmak için atomların rastgele sapmasını (clinamen) ekledi.'),
  ('Aristoteles\'in dört nedenle ilgili açıklaması ile Demokritos\'un atomculuğu arasındaki başlıca fark nedir?', 'Aristoteles erek (amaç) nedeni de kabul eder, atomcular yalnız mekanik nedenlerle açıklar', ['İkisi de yalnız erek nedeni kabul eder', 'İkisi de nedenselliği reddeder', 'İkisi de tanrıları neden sayar'], 'Atomcular doğayı amaçsız mekanik çarpışmalarla açıklar; Aristoteles ise doğada amaca yönelik oluşu da hesaba katar.'),
  ('Skolastiğin evrenselleri tartışması ile Platon\'un idealar kuramı arasındaki bağ nedir?', 'Aşırı gerçekçilik Platon\'un ideaların bağımsız varlığı görüşünün bir uzantısıdır', ['Nominalizm Platon\'un idealar kuramının ta kendisidir', 'Kavramcılık Platon\'u reddeder ama atomcudur', 'Hiçbir bağ yoktur'], 'Evrensellerin bireylerden önce gerçek varlıklar olduğunu söyleyen gerçekçilik, Platoncu idealar öğretisinin Orta Çağ\'daki yankısıdır.'),
  ('MÖ 404\'te Atina\'da iktidara gelen Otuz Tiranlar\'ın Sokrates\'in yargılanması bağlamındaki önemi nedir?', 'Öğrencileri arasında Kritias gibi Otuz Tiran üyelerinin bulunması, onu siyasal açıdan şüpheli kılmıştır', ['Otuz Tiran\'ın Sokrates\'i kurtarması', 'Otuz Tiran\'ın Sokrates\'i idam etmesi', 'Sokrates\'in Otuz Tiran\'ı kurması'], 'Sokrates\'in yakın çevresinden bazıları oligarşi taraftarıydı. Demokrasi geri geldiğinde bu durum Sokrates\'e yönelik güvensizliği artırdı.'),
  ('Pyrrhon\'un felsefesi nasıl etkilenmiş olabilir?', 'İskender\'in seferine katılarak Hindistan\'daki bilgelerle karşılaşmasından', ['Roma\'da okumasından', 'Mısır\'da öğretmenlik yapmasından', 'Sicilya\'da tiyatro oyunculuğundan'], 'Anlatıya göre Pyrrhon İskender\'in ordusuyla Hindistan\'a gitti ve oradaki çıplak bilgelerle karşılaşması, yargıyı askıya alma tutumunu etkiledi.'),
  ('Çin siyaset düşüncesinde "Göğün Buyruğu" (Tianming) neyi anlatır?', 'Hükümdarın meşruiyetinin gök tarafından verildiği ve adaletsiz yönetimde geri alınabileceği düşüncesini', ['Hükümdarın tanrı olduğunu', 'Halkın yönetimde hiçbir hakkı olmadığını', 'Yönetimin yalnız soy yoluyla geçtiğini'], 'Gök buyruğu anlayışına göre yönetici erdemliyken meşrudur; zulüm halinde iktidar hakkını yitirir ve devrilmesi haklı sayılır.'),
  ('Konfüçyüs\'ün yaşadığı çağda Çin\'in siyasal durumu nasıl nitelenebilir?', 'Merkezî düzenin zayıfladığı, feodal devletlerin birbirine savaş açtığı bir dönem', ['Güçlü bir tek imparatorluk dönemi', 'Moğol egemenliği dönemi', 'Cumhuriyet dönemi'], 'Konfüçyüs Bahar-Sonbahar döneminde yaşadı; toplumsal çalkantı onu ahlaki düzen ve erdemli yönetim arayışına yöneltti.'),
  ('Ockham\'ın Tanrı anlayışında öne çıkan "mutlak güç" vurgusu hangi sonuca yol açar?', 'Tanrı\'nın iradesinin doğa düzenine ve akılcı kurallara bağlı kalmadığı', ['Tanrı\'nın aklın zorunluluklarına bağlı olduğu', 'Tanrı\'nın hiç iradesinin olmadığı', 'Evrenin zorunlu olduğu'], 'Ockham ve diğer geç skolastikler Tanrı\'nın iradesinin mutlak olduğunu vurgulayarak doğadaki düzenin zorunlu değil olumsal olduğunu savundu; bu yaklaşım deneyin önemini artırdı.'),
  ('Kelam tartışmasında "iyi ve kötünün akılla bilinip bilinemeyeceği" konusunda Mutezile ile Eş\'ariyye\'nin görüşü nasıl ayrışır?', 'Mutezile iyi-kötüyü aklın bilebileceğini, Eş\'ariyye ise vahyin belirlediğini savunur', ['İkisi de yalnız akla dayanır', 'İkisi de yalnız vahye dayanır', 'İkisi de iyi-kötünün bulunmadığını söyler'], 'Mutezile aklî hüsün-kubuh anlayışını (aklın iyi-kötüyü kavrayabilmesini) savunur; Eş\'ariyye ise iyi ve kötünün Tanrı\'nın buyruğuyla belirlendiğini söyler.'),
  ('Evrenin başlangıcı sorusunda Platon ile Aristoteles\'in görüşü nasıl ayrışır?', 'Platon\'un Timaios\'unda evren demiurgos tarafından oluşturulmuş, Aristoteles\'te ise evren ezelîdir', ['İkisi de evrenin yoktan yaratıldığını söyler', 'İkisi de evrenin rastlantıyla oluştuğunu söyler', 'İkisi de evrenin yok olacağını söyler'], 'Platon evrenin zaman içinde yapıldığını (ya da öyle anlatıldığını), Aristoteles ise hareketin ve evrenin başlangıcının bulunmadığını savunur.'),
  ('Stoacıların tanrı anlayışı Epikurosçulardan nasıl ayrılır?', 'Stoacılar tanrıyı evrene içkin yönetici akıl (logos) sayar, Epikurosçular tanrıların evrenle ilgilenmediğini söyler', ['İkisi de tanrıyı reddeder', 'İkisi de aynı görüştedir', 'İkisi de tanrıyı yalnız doğaüstü sayar'], 'Stoa panteist ve tanrısal öngörüye (pronoia) inanır; Epikuros ise tanrıların insan işlerine karışmadığını savunur.'),
  ('Thales\'e atfedilen "Her şey tanrılarla doludur" sözü onun doğa anlayışı hakkında neyi düşündürür?', 'Doğadaki canlılık ve hareketin tanrısal bir ilkeyle ilişkili görüldüğünü', ['Tanrıların hiç olmadığını', 'Evrenin yalnız insanlardan oluştuğunu', 'Evrenin hareketsiz olduğunu'], 'Aristoteles bu sözü Thales\'in canlılık ve ruh fikriyle ilişkilendirir. Bu bakış, Milet doğa felsefesinin doğaüstü yerine doğal nedenleri aradığını gösterir.'),
];
